let mut tera = Tera::new("templates/**/*.html")?;
tera.register_filter("money", |value: &Value, kwargs: Kwargs| {
    let cents: i64 = value.as_i64().unwrap_or_default();      // fallback: never fail the page
    let currency: String = kwargs.get("currency")?.unwrap_or_else(|| "EUR".into());
    Ok(Value::normal_string(&format!("{:.2} {}", cents as f64 / 100.0, currency)))
});
// view:  {{ order.total | money(currency="EUR") }}

