#[derive(Template)]
#[template(ext = "html", source = "<span class=\"money\">{{ total }}</span>")]
struct Money<'a> { cents: i64, currency: &'a str }

impl Money<'_> {
    fn total(&self) -> String {              // helper: plain method on the typed context
        format!("{:.2} {}", self.cents as f64 / 100.0, self.currency)
    }
}
